1 | /**
2 |  * Minimal client for the EPOCH API. Every path is relative: in development Vite
3 |  * proxies /api to the API (EPOCH_API_URL), and the hosted build is served from
4 |  * the API's own origin.
5 |  */
6 | 
7 | export class ApiError extends Error {
8 |   readonly status: number;
9 |   /** True when the API could not be reached at all (network error or dev-proxy failure). */
10 |   readonly unreachable: boolean;
11 |   readonly path: string;
12 | 
13 |   constructor(message: string, status: number, path: string, unreachable = false) {
14 |     super(message);
15 |     this.name = 'ApiError';
16 |     this.status = status;
17 |     this.path = path;
18 |     this.unreachable = unreachable;
19 |   }
20 | }
21 | 
22 | export const START_API_HINT = 'Start the API with pnpm dev';
23 | 
24 | async function request<T>(method: 'GET' | 'POST', path: string, body?: unknown): Promise<T> {
25 |   let res: Response;
26 |   try {
27 |     res = await fetch(path, {
28 |       method,
29 |       headers: body === undefined ? { Accept: 'application/json' } : { Accept: 'application/json', 'Content-Type': 'application/json' },
30 |       body: body === undefined ? undefined : JSON.stringify(body)
31 |     });
32 |   } catch {
33 |     throw new ApiError(`Cannot reach the EPOCH API. ${START_API_HINT}.`, 0, path, true);
34 |   }
35 | 
36 |   const isJson = (res.headers.get('content-type') ?? '').includes('application/json');
37 |   const payload: unknown = isJson ? await res.json().catch(() => undefined) : undefined;
38 | 
39 |   if (!res.ok) {
40 |     // The Vite dev proxy answers a plain-text 5xx when nothing listens behind it.
41 |     if (!isJson && res.status >= 500) {
42 |       throw new ApiError(`Cannot reach the EPOCH API. ${START_API_HINT}.`, res.status, path, true);
43 |     }
44 |     const message = payload && typeof payload === 'object' && 'error' in payload && typeof (payload as { error: unknown }).error === 'string'
45 |       ? (payload as { error: string }).error
46 |       : `${method} ${path} failed with ${res.status}`;
47 |     throw new ApiError(message, res.status, path);
48 |   }
49 |   if (!isJson) {
50 |     // index.html instead of JSON means the request never reached the API.
51 |     throw new ApiError(`Cannot reach the EPOCH API. ${START_API_HINT}.`, res.status, path, true);
52 |   }
53 |   return payload as T;
54 | }
55 | 
56 | export const apiGet = <T>(path: string): Promise<T> => request<T>('GET', path);
57 | export const apiPost = <T>(path: string, body: unknown = {}): Promise<T> => request<T>('POST', path, body);
58 | 
59 | /**
60 |  * A short, human explanation of a failed call. Write-specific statuses follow
61 |  * the public demo contract (docs/API_CONTRACT.md).
62 |  */
63 | export function describeError(error: unknown, context: 'read' | 'write' | 'restore' = 'read'): string {
64 |   if (error instanceof ApiError) {
65 |     if (error.unreachable) return `Cannot reach the EPOCH API. ${START_API_HINT}.`;
66 |     if (context !== 'read') {
67 |       if (error.status === 429) return 'Busy, try again in a moment.';
68 |       if (error.status === 409 && context === 'restore') return 'Restore already running.';
69 |       if (error.status === 403) return 'Read-only in the public demo.';
70 |     }
71 |     return error.message;
72 |   }
73 |   return error instanceof Error ? error.message : String(error);
74 | }
75 | 
76 | export const isNotFound = (error: unknown): boolean => error instanceof ApiError && error.status === 404;
77 |

