1 | /**
2 |  * One shared EventSource on GET /api/v1/stream for the whole console. Hooks
3 |  * subscribe to topics and refetch when something they show changes.
4 |  *
5 |  * The browser reconnects by itself (sending Last-Event-ID); when the stream
6 |  * fails hard (the API is down and the dev proxy answers an error), we reconnect
7 |  * with backoff. After any reconnect every subscriber refetches, because events
8 |  * may have been missed.
9 |  */
10 | 
11 | export type LiveTopic = 'activity' | 'task' | 'mutation' | 'drift' | 'invariant' | 'workflow' | 'reset';
12 | export type StreamStatus = 'connecting' | 'live' | 'reconnecting' | 'offline';
13 | 
14 | type Listener = (topic: LiveTopic, data: unknown) => void;
15 | 
16 | const STREAM_PATH = '/api/v1/stream';
17 | const EVENT_TOPICS: Record<string, LiveTopic> = {
18 |   'epoch.activity': 'activity',
19 |   'epoch.task': 'task',
20 |   'epoch.mutation': 'mutation',
21 |   'epoch.drift': 'drift',
22 |   'epoch.invariant': 'invariant',
23 |   'epoch.workflow': 'workflow'
24 | };
25 | 
26 | const listeners = new Set<Listener>();
27 | const statusListeners = new Set<() => void>();
28 | let source: EventSource | null = null;
29 | let status: StreamStatus = 'connecting';
30 | let failures = 0;
31 | let retryTimer: ReturnType<typeof setTimeout> | undefined;
32 | 
33 | function setStatus(next: StreamStatus): void {
34 |   if (status === next) return;
35 |   status = next;
36 |   for (const listener of [...statusListeners]) listener();
37 | }
38 | 
39 | function publish(topic: LiveTopic, data: unknown): void {
40 |   for (const listener of [...listeners]) listener(topic, data);
41 | }
42 | 
43 | function scheduleReconnect(): void {
44 |   if (retryTimer) return;
45 |   const delay = Math.min(15_000, 1_000 * 2 ** Math.min(failures, 4));
46 |   failures += 1;
47 |   retryTimer = setTimeout(() => {
48 |     retryTimer = undefined;
49 |     connect();
50 |   }, delay);
51 | }
52 | 
53 | function connect(): void {
54 |   if (source || typeof EventSource === 'undefined') return;
55 |   const es = new EventSource(STREAM_PATH);
56 |   source = es;
57 | 
58 |   /** Up (again): after a drop, every subscriber refetches what it may have missed. */
59 |   const markLive = (): void => {
60 |     if (source !== es || status === 'live') return;
61 |     const recovered = status === 'reconnecting' || status === 'offline';
62 |     failures = 0;
63 |     setStatus('live');
64 |     if (recovered) publish('reset', null);
65 |   };
66 | 
67 |   es.onopen = markLive;
68 | 
69 |   es.onerror = () => {
70 |     if (es.readyState === EventSource.CLOSED) {
71 |       es.close();
72 |       if (source === es) source = null;
73 |       setStatus('offline');
74 |       scheduleReconnect();
75 |     } else {
76 |       // The browser reconnects by itself (with Last-Event-ID).
77 |       setStatus('reconnecting');
78 |     }
79 |   };
80 | 
81 |   // The server sends a `ready` event immediately on connect; use it as the
82 |   // definitive signal that the stream is live.
83 |   es.addEventListener('ready', markLive);
84 | 
85 |   for (const [name, topic] of Object.entries(EVENT_TOPICS)) {
86 |     es.addEventListener(name, event => {
87 |       markLive();
88 |       let data: unknown;
89 |       try {
90 |         data = JSON.parse((event as MessageEvent<string>).data);
91 |       } catch {
92 |         return;
93 |       }
94 |       publish(topic, data);
95 |     });
96 |   }
97 | }
98 | 
99 | /** Listen to live events; the stream opens on the first subscriber and stays open. */
100 | export function subscribeLive(listener: Listener): () => void {
101 |   listeners.add(listener);
102 |   connect();
103 |   return () => {
104 |     listeners.delete(listener);
105 |   };
106 | }
107 | 
108 | /** Ask every live hook to refetch (after a demo restore, for example). */
109 | export function refreshAll(): void {
110 |   publish('reset', null);
111 | }
112 | 
113 | export function subscribeStreamStatus(listener: () => void): () => void {
114 |   statusListeners.add(listener);
115 |   connect();
116 |   return () => {
117 |     statusListeners.delete(listener);
118 |   };
119 | }
120 | 
121 | export const getStreamStatus = (): StreamStatus => status;
122 |

