    transform: translate3d(0, 1200%, 0);
    opacity: 0;
  }
}

.particle-runner-x {
  animation: particle-run-x 9s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  will-change: transform;
}

.particle-runner-x-delayed {
  animation: particle-run-x 13s cubic-bezier(0.4, 0, 0.2, 1) infinite 4s;
  will-change: transform;
}

.particle-runner-y {
  animation: particle-run-y 11s cubic-bezier(0.4, 0, 0.2, 1) infinite 2s;
  will-change: transform;
}

/* =========================================================================
   SILK-SMOOTH GPU LENS SHIFT (Lag-Free, Snappy 340ms, Zero Font Scaling Re-raster)
   Pure translate3d + opacity running on the GPU compositor at solid 60fps
   ========================================================================= */

@keyframes lens-shift-forward {
  0% {
    opacity: 0;
    transform: translate3d(0, 6px, 0);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

@keyframes lens-shift-reverse {
  0% {
    opacity: 0;
    transform: translate3d(0, -6px, 0);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

.lens-shift-forward {
  animation: lens-shift-forward 200ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: opacity, transform;
  backface-visibility: hidden;
}

.lens-shift-reverse {
  animation: lens-shift-reverse 200ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
  will-change: opacity, transform;
  backface-visibility: hidden;
}

/* =========================================================================
   APPROVAL REQUIRED & TRAJECTORY DRIFT — SLOW, CALM PULSE (LONG 6s INTERVAL)
   subtle → noticeable → stable rather than pop → disappear → pop
   ========================================================================= */

@keyframes status-breathe-warn-slow {
  0%, 84%, 100% {
    transform: scale(1);
    opacity: 0.92;
    box-shadow: 0 0 0 0 rgba(245, 158, 11, 0);
  }
  92% {
    transform: scale(1.06);
    opacity: 1;
    box-shadow: 0 0 8px 1.5px rgba(245, 158, 11, 0.35);
  }
}

.animate-pulse-warn-slow {
  animation: status-breathe-warn-slow 6s ease-in-out infinite;
}

/* Active Stage Subtle Progress */
@keyframes active-stage-glow {
  0%, 100% {
    border-color: rgba(56, 189, 248, 0.5);
    box-shadow: 0 0 10px rgba(56, 189, 248, 0.12);
  }
  50% {
    border-color: rgba(56, 189, 248, 0.85);
    box-shadow: 0 0 16px rgba(56, 189, 248, 0.22);
  }
}

.animate-active-stage {
  animation: active-stage-glow 3s ease-in-out infinite;
}

/* Live Events indicator breathing */
@keyframes status-breathe-live {
  0%, 100% {
    transform: scale(1);
    opacity: 0.9;
  }
  50% {
    transform: scale(1.18);
    opacity: 1;
    box-shadow: 0 0 6px rgba(16, 185, 129, 0.6);
  }
}

.animate-pulse-live {
  animation: status-breathe-live 2.4s ease-in-out infinite;
}

/* Causal Edge Flowing Dashes */
@keyframes edge-dash-motion {
  0% {
    stroke-dashoffset: 32;
  }
  100% {
    stroke-dashoffset: 0;
  }
}

.animate-edge-flow {
  stroke-dasharray: 6 6;
  animation: edge-dash-motion 1.4s linear infinite;
}

/* Event Entrance */
@keyframes new-event-slide {
  0% {
    opacity: 0;
    transform: translate3d(0, -6px, 0);
  }
  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

.animate-event-in {
  animation: new-event-slide 240ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Branch Draw Sequence (Futures) */
@keyframes branch-draw-down {
  0% {
    stroke-dashoffset: 120;
    opacity: 0;
  }
  100% {
    stroke-dashoffset: 0;
    opacity: 1;
  }
}

.animate-branch-draw {
  stroke-dasharray: 120;
  animation: branch-draw-down 450ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Button Micro-Interactions */
.btn-control {
  transition: transform 160ms cubic-bezier(0.16, 1, 0.3, 1), background-color 160ms ease, border-color 160ms ease, color 160ms ease;
}
.btn-control:hover {
  transform: translateY(-1px);
}
.btn-control:active {
  transform: translateY(0.5px) scale(0.99);
}

/* Reduced Motion Safety */
@media (prefers-reduced-motion: reduce) {
  .live-moving-grid,
  .live-scan-bar,
  .particle-runner-x,
  .particle-runner-x-delayed,
  .particle-runner-y,
  .lens-shift-forward,
  .lens-shift-reverse,
  .animate-pulse-warn-slow,
  .animate-pulse-live,
  .animate-active-stage,
  .animate-edge-flow,
  .animate-event-in,
  .animate-branch-draw {
    animation: none !important;
    transform: none !important;
  }
}

/* =========================================================================
   PROSE-REPORT: Markdown report rendered HTML styles
   ========================================================================= */

.prose-report {
  font-family: var(--font-sans);
  color: #d4d4d8;
  font-size: 0.8125rem;
  line-height: 1.7;
}

.prose-report h1 {
  font-size: 1.1rem;
  font-weight: 700;
  color: #f4f4f5;
  margin: 1.25rem 0 0.5rem;
  padding-bottom: 0.35rem;
  border-bottom: 1px solid #27272a;
  letter-spacing: -0.01em;
}

.prose-report h2 {
  font-size: 0.9375rem;
  font-weight: 700;
  color: #e4e4e7;
  margin: 1.1rem 0 0.4rem;
}

.prose-report h3 {
  font-size: 0.8125rem;
  font-weight: 700;
  color: #d4d4d8;
  margin: 0.9rem 0 0.3rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.prose-report h4 {
  font-size: 0.75rem;
  font-weight: 600;
  color: #a1a1aa;
  margin: 0.75rem 0 0.25rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.prose-report p {
  margin: 0 0 0.65rem;
}

.prose-report ul {
  list-style: none;
  padding: 0;
  margin: 0 0 0.65rem;
}

.prose-report ul li {
  padding-left: 1.25rem;
  position: relative;
  margin-bottom: 0.2rem;
}

.prose-report ul li::before {
  content: '—';
  position: absolute;
  left: 0;
  color: #52525b;
}

.prose-report strong {
  color: #f4f4f5;
  font-weight: 600;
}

.prose-report code {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  background: #18181b;
  border: 1px solid #27272a;
  border-radius: 3px;
  padding: 0.1em 0.35em;
  color: #fb923c;
}

.prose-report table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.75rem;
  font-family: var(--font-mono);
  margin: 0 0 0.9rem;
}

.prose-report thead tr {
  background: #18181b;
  border-bottom: 1px solid #3f3f46;
}

.prose-report th {
  text-align: left;
  padding: 0.4rem 0.6rem;
  color: #a1a1aa;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

.prose-report td {
  padding: 0.35rem 0.6rem;
  border-bottom: 1px solid #27272a;
  color: #d4d4d8;
  vertical-align: top;
}

.prose-report tbody tr:hover td {
  background: #18181b;
}

